"""Frigate configuration for approved saved devices (ADR-0003).

Renders the full config from the tracked template plus the devices an
operator approved. Stream sources are only `{FRIGATE_DEV_<id>_MAIN}` /
`_SUB` placeholders: the credential-bearing URLs go into secret files that
Frigate reads at startup, so no password can appear in the config file,
in Frigate's /api/config/raw or in anything sent to the browser.
`FrigateDevice` deliberately has no credential fields.
"""

import copy
import re
from dataclasses import dataclass

import yaml

GENERATED_HEADER = (
    "# Generated by the AI Surveillance api from deploy/frigate/config.yml plus the saved\n"
    "# devices switched to \"Use in Frigate\". Do not edit: \"Apply to Frigate\" overwrites it.\n"
    "# Stream URLs are {FRIGATE_*} placeholders; the values are secret files in /run/secrets.\n"
)

MAX_DEVICES = 32
RESTREAM = "rtsp://127.0.0.1:8554/"  # go2rtc inside the Frigate container
DETECT_FPS = 5
_DEVICE_ID = re.compile(r"^[0-9a-f]{32}$")
_MAX_NAME = 40
_MAX_SIDE = 8192
# Settings a new camera takes from the template's first camera.
_INHERITED = ("objects", "record", "snapshots")


@dataclass(frozen=True)
class FrigateDevice:
    """An approved saved device, as far as Frigate's config needs it. No credentials by design."""

    id: str
    name: str
    has_sub: bool
    detect_width: int | None
    detect_height: int | None


def secret_name(device_id: str, stream: str) -> str:
    """The `FRIGATE_*` name of a device stream's URL (a file in /run/secrets for Frigate)."""
    if not _DEVICE_ID.match(device_id):
        raise ValueError("invalid device id")
    if stream not in ("main", "sub"):
        raise ValueError("stream must be 'main' or 'sub'")
    return f"FRIGATE_DEV_{device_id.upper()}_{stream.upper()}"


def _slug(name: str) -> str:
    slug = re.sub(r"[^a-z0-9_]+", "_", name.lower()).strip("_")[:_MAX_NAME].strip("_")
    return slug or "camera"


def _load_template(text: str) -> dict:
    try:
        config = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise ValueError(f"the Frigate template is not valid YAML: {exc}") from exc
    if not isinstance(config, dict):
        raise ValueError("the Frigate template must be a mapping")
    if not isinstance(config.get("cameras"), dict):
        raise ValueError("the Frigate template needs a 'cameras' mapping")
    go2rtc = config.get("go2rtc")
    if not isinstance(go2rtc, dict) or not isinstance(go2rtc.get("streams"), dict):
        raise ValueError("the Frigate template needs a 'go2rtc.streams' mapping")
    return config


def _detect(device: FrigateDevice) -> dict:
    detect: dict = {"enabled": True}
    w, h = device.detect_width, device.detect_height
    if isinstance(w, int) and isinstance(h, int) and 0 < w <= _MAX_SIDE and 0 < h <= _MAX_SIDE:
        detect.update(width=w, height=h)  # otherwise Frigate measures the stream itself
    detect["fps"] = DETECT_FPS
    return detect


def render_config(template_text: str, devices: list[FrigateDevice]) -> tuple[str, dict[str, str]]:
    """Return (config text, {device id: Frigate camera name}).

    Template cameras and streams are kept unchanged. Camera names are derived
    from the operator's names; a clash gets the first 6 characters of the
    device id appended, so the same input always gives the same names.
    """
    config = _load_template(template_text)
    if len(devices) > MAX_DEVICES:
        raise ValueError(f"at most {MAX_DEVICES} devices can be applied")
    if len({d.id for d in devices}) != len(devices):
        raise ValueError("a device is listed twice")

    cameras: dict = config["cameras"]
    streams: dict = config["go2rtc"]["streams"]
    reference = next(iter(cameras.values()), None) or {}
    taken = set(cameras) | set(streams)
    names: dict[str, str] = {}

    for device in devices:
        secret_name(device.id, "main")  # validates the id
        wanted = [_slug(device.name), f"{_slug(device.name)}_{device.id[:6]}"]
        for name in wanted:
            needed = {name, f"{name}_sub"} if device.has_sub else {name}
            if not needed & taken:
                break
        else:
            raise ValueError(f"no free Frigate camera name for device {device.name!r}")
        taken |= needed
        names[device.id] = name

        streams[name] = [f"{{{secret_name(device.id, 'main')}}}"]
        if device.has_sub:
            streams[f"{name}_sub"] = [f"{{{secret_name(device.id, 'sub')}}}"]
            inputs = [
                {"path": RESTREAM + name, "input_args": "preset-rtsp-restream", "roles": ["record"]},
                {"path": f"{RESTREAM}{name}_sub", "input_args": "preset-rtsp-restream", "roles": ["detect"]},
            ]
            live = {"Sub": f"{name}_sub", "Main": name}
        else:
            inputs = [{"path": RESTREAM + name, "input_args": "preset-rtsp-restream", "roles": ["record", "detect"]}]
            live = {"Main": name}

        camera = {"enabled": True, "ffmpeg": {"inputs": inputs}, "detect": _detect(device), "live": {"streams": live}}
        for key in _INHERITED:
            if key in reference:
                camera[key] = copy.deepcopy(reference[key])
        cameras[name] = camera

    text = yaml.safe_dump(config, sort_keys=False, default_flow_style=False, allow_unicode=True)
    return GENERATED_HEADER + text, names
